import { Accessor, createEffect, createMemo, on } from "solid-js";
import { createStore, produce } from "solid-js/store";

import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";
import { createArraySignal, createPolledSignal } from "#core/ui-next/utilities/solid-utilities.js";

export interface ReactiveGameSetupParameter extends GameSetupParameter {
	setValue: (value: GameSetupParameterValue) => void;
	update: () => void;
	destroyed: boolean;
	setDestroyed: (value: boolean) => void;
}

export interface ConfigurationPlayerSlot {
	playerId: PlayerId;
	isLocalPlayer: boolean;
	slotStatus: SlotStatus;
	setSlotStatus: (value: SlotStatus) => void;
}

export type GameParametersName = "Difficulty" | "GameSpeeds" | "Map" | "MapSize" | "AgeTransitionSetting" | string;
export type GameSetupParameters = Record<GameParametersName, ReactiveGameSetupParameter>;

export type PlayerParameterName = "PlayerLeader" | "PlayerCivilization" | "AgeTransitionPlayerCivilization" | string;
export type PlayerSetupParameters = Record<PlayerParameterName, ReactiveGameSetupParameter>;

/**
 * Usage: GameParametersModel.get().[ParameterName]
 */
export type GameSetupParametersModel = GameSetupParameters;
export interface GameSetupParametersByGroupModel {
	groups: Record<string, GameSetupParameters>;
	groupNames: ReadonlyMap<string, string>;
}

export interface PlayerSlotConfiguration {
	allSlots: Accessor<ConfigurationPlayerSlot[]>;
	openSlots: Accessor<ConfigurationPlayerSlot[]>;
	activeSlots: Accessor<ConfigurationPlayerSlot[]>;
	reload: () => void;
}

/**
 * Usage: GameParametersModel.get().players[playerId].[ParameterName]
 */
export interface PlayerSetupParametersModel {
	players: Record<number, PlayerSetupParameters>;
	configuration: PlayerSlotConfiguration;
}

export interface CombinedSetupParamaterModels {
	gameParametersModel: GameSetupParametersModel;
	gameParametersByGroupModel: GameSetupParametersByGroupModel;
	playerParametersModel: PlayerSetupParametersModel;
	forceRefresh: () => void;
	resetToDefaults: () => void;
}

const playerDependantGameParamters = new Set(["MapSize"]);

function createBaseSetupParameter(
	getFunc: () => GameSetupParameter | null,
	setFunc: (value: GameSetupParameterValue) => void,
): ReactiveGameSetupParameter | null {
	const initialData = getFunc();

	if (!initialData) {
		return null;
	}

	const [parameter, setParameter] = createStore<ReactiveGameSetupParameter>({
		...initialData,

		destroyed: false,

		update: () => {
			const newData = getFunc();
			if (newData) {
				setParameter(produce((state) => Object.assign(state, newData)));
			}
		},

		setValue: setFunc,

		setDestroyed: (value: boolean) => {
			setParameter("destroyed", value);
		},
	});

	return parameter;
}

function createGameSetupParameter(parameterId: ParameterId): ReactiveGameSetupParameter | null {
	const getFunc = () => GameSetup.findGameParameter(parameterId);
	const setFunc = (value: GameSetupParameterValue) => GameSetup.setGameParameterValue(parameterId, value);

	return createBaseSetupParameter(getFunc, setFunc);
}

function createPlayerSetupParameter(playerId: PlayerId, parameterId: ParameterId): ReactiveGameSetupParameter | null {
	const getFunc = () => GameSetup.findPlayerParameter(playerId, parameterId);
	const setFunc = (value: GameSetupParameterValue) => GameSetup.setPlayerParameterValue(playerId, parameterId, value);

	const playerParams = createBaseSetupParameter(getFunc, setFunc) as ReactiveGameSetupParameter;

	return playerParams;
}

function createPlayerConfiguration(): PlayerSlotConfiguration {
	const [allSlots, mutateAllSlots] = createArraySignal<ConfigurationPlayerSlot>([]);

	const reload = () => {
		const maxPlayers = Configuration.getMap().maxMajorPlayers;

		mutateAllSlots((slots) => {
			if (slots.length > maxPlayers) {
				slots.length = maxPlayers;
			}

			for (let playerId = 0; playerId < maxPlayers; ++playerId) {
				const playerConfig = Configuration.getPlayer(playerId);
				const slotStatus = playerConfig.slotStatus;

				const setSlotStatus = (slotStatus: SlotStatus) => {
					const playerEdit = Configuration.editPlayer(playerId);

					if (playerEdit) {
						playerEdit.setSlotStatus(slotStatus);
						playerEdit.setAsMajorCiv();
					}

					reload();
				};

				const existingSlot = slots.find((slot) => slot.playerId == playerId);

				if (existingSlot) {
					existingSlot.slotStatus = slotStatus;
				} else {
					const isLocalPlayer = playerId == GameContext.localPlayerID;
					slots.push({
						playerId,
						isLocalPlayer,
						slotStatus,
						setSlotStatus,
					});
				}
			}
		});
	};

	const activeSlots = createMemo(() => {
		return allSlots().filter((s) => !(s.slotStatus == SlotStatus.SS_CLOSED || s.slotStatus == SlotStatus.SS_OPEN));
	});

	const openSlots = createMemo(() => {
		return allSlots().filter((s) => s.slotStatus == SlotStatus.SS_CLOSED || s.slotStatus == SlotStatus.SS_OPEN);
	});

	reload();

	return { reload, allSlots, activeSlots, openSlots };
}

// Because batch updates are mixed, we have to update both models at the same time
function createCombinedSetupModels(): CombinedSetupParamaterModels {
	let prevGameSetupRevision = 0;
	// TODO: Convert this to use a game event instead of polling.
	const [currentId] = createPolledSignal(() => GameSetup.currentRevision, 150);

	const [gameParameters, setGameParameters] = createStore<GameSetupParameters>({});
	const groupNames = new Map<string, string>();
	const [groupGameParameters, setGroupGameParameters] = createStore<GameSetupParametersByGroupModel>({
		groupNames,
		groups: {},
	});

	const parameterGroups = Database.query("config", "SELECT * FROM ParameterGroups") ?? [];
	for (const row of parameterGroups) {
		const name = Locale.compose((row.Name as string | undefined) ?? "");
		const groupId = Locale.compose((row.GroupID as string | undefined) ?? "");
		groupNames.set(groupId, name);
	}

	const [playerParameters, setPlayerParameters] = createStore<Record<number, PlayerSetupParameters>>({});
	const playerParametersModel: PlayerSetupParametersModel = {
		players: playerParameters,
		configuration: createPlayerConfiguration(),
	};

	function addToGroup(groupId: string, param: ReactiveGameSetupParameter) {
		const group = GameSetup.resolveString(param.group);
		if (group) {
			// PTR1: omit legacy options for now
			if (group == "LegacyOptions") {
				return;
			}

			// Ensure group exists
			if (!groupGameParameters.groups[group]) {
				// Force set name on the group
				const emptyGroup = { name: groupNames.get(groupId) ?? groupId } as unknown as GameSetupParameters;
				setGroupGameParameters("groups", group, emptyGroup);
			}

			setGroupGameParameters("groups", group, groupId, param);
		}
	}

	function updateParamValue(change: GameSetupParameterChange, parameter: ReactiveGameSetupParameter) {
		if (change.destroyed) {
			parameter.setDestroyed(true);
		} else {
			parameter.update();
			if (change.created) {
				parameter.setDestroyed(false);
			}
		}
	}

	function addPlayerParameter(playerId: number, paramName: string) {
		const newParameter = createPlayerSetupParameter(playerId, paramName);
		if (newParameter) {
			// Ensure player exists
			if (!playerParameters[playerId]) {
				setPlayerParameters(playerId, {});
			}

			setPlayerParameters(playerId, paramName, newParameter);
		}
	}

	function addGameParameter(paramName: string) {
		const newParameter = createGameSetupParameter(paramName);
		if (newParameter) {
			setGameParameters(paramName, newParameter);
			addToGroup(paramName, newParameter);
		}
	}

	function updateParameterChanges(changes: GameSetupParameterChange[]) {
		let playerParametersUpdated = false;

		for (const change of changes) {
			const paramName = GameSetup.resolveString(change.parameterID);

			if (!paramName) {
				return;
			}

			if (change.playerID !== undefined) {
				// This is a player parameter
				const parameter = playerParameters[change.playerID]?.[paramName];
				playerParametersUpdated = true;

				if (parameter) {
					updateParamValue(change, parameter);
				} else if (change.created) {
					addPlayerParameter(change.playerID, paramName);
				}
			} else if (change.teamID === undefined) {
				// This is a game parameter
				const parameter = gameParameters[paramName];

				// If this game param causes player param updates, update them too
				if (playerDependantGameParamters.has(paramName)) {
					playerParametersUpdated = true;
				}

				if (parameter) {
					updateParamValue(change, parameter);
				} else if (change.created) {
					addGameParameter(paramName);
				}
			}
		}

		if (playerParametersUpdated) {
			// If player parameters were updated, we need to refresh slot status (it is not reactive)
			playerParametersModel.configuration.reload();
		}
	}

	function updatePlayerParamters() {
		let playerParametersUpdated = false;
		for (const playerId of Configuration.getGame().participatingPlayerIDs) {
			const gamePlayerParameters = GameSetup.getPlayerParameters(playerId);
			for (const parameter of gamePlayerParameters) {
				const paramName = GameSetup.resolveString(parameter.ID);
				if (!paramName) {
					break;
				}

				const existingParameter = playerParameters[playerId]?.[paramName];
				if (existingParameter) {
					existingParameter.update();
					playerParametersUpdated = true;
				} else {
					addPlayerParameter(playerId, paramName);
					playerParametersUpdated = true;
				}
			}
		}

		if (playerParametersUpdated) {
			// If player parameters were updated, we need to refresh slot status (it is not reactive)
			playerParametersModel.configuration.reload();
		}
	}

	function updateGameParameters() {
		for (const parameter of GameSetup.getGameParameters()) {
			const paramName = GameSetup.resolveString(parameter.ID);
			if (!paramName) {
				break;
			}

			const existingParameter = gameParameters[paramName];
			if (existingParameter) {
				existingParameter.update();
			} else {
				addGameParameter(paramName);
			}
		}
	}

	createEffect(
		on(
			currentId,
			(value: number) => {
				if (value != prevGameSetupRevision) {
					const changes = GameSetup.getParameterChanges(prevGameSetupRevision);
					if (changes == null) {
						updateGameParameters();
						updatePlayerParamters();
					} else if (changes.length > 0) {
						updateParameterChanges(changes);
					}
					prevGameSetupRevision = value;
				}
			},
			{ defer: true },
		),
	);

	function resetToDefault() {
		GameSetup.resetSavedCreateGameSettings();
		Configuration.editGame()?.reset(GameModeTypes.SINGLEPLAYER);
	}

	function forceRefresh() {
		updateGameParameters();
		updatePlayerParamters();
		prevGameSetupRevision = GameSetup.currentRevision;
	}

	// eslint-disable-next-line solid/reactivity
	forceRefresh();

	return {
		gameParametersModel: gameParameters,
		gameParametersByGroupModel: groupGameParameters,
		playerParametersModel,
		forceRefresh,
		resetToDefaults: resetToDefault,
	};
}

/**
 * Note: Because we have multiple models generated by a single function we need to make
 *       a lazily initialized shared object - do not copy paste this unless you have the same requirements.
 */
let combinedSetupModelsInstance: CombinedSetupParamaterModels | undefined = undefined;
const combinedSetupModels = () => {
	combinedSetupModelsInstance ??= createCombinedSetupModels();
	return combinedSetupModelsInstance;
};

export const SetupParametersModel = ModelRegistry.register("SetupParametersModel", ModelLifecycle.Singleton, () =>
	combinedSetupModels(),
);

export const PlayerSetupParametersModel = ModelRegistry.register(
	"PlayerSetupParametersModel",
	ModelLifecycle.Singleton,
	() => combinedSetupModels().playerParametersModel,
);

export const GameSetupParametersModel = ModelRegistry.register(
	"GameSetupParametersModel",
	ModelLifecycle.Singleton,
	() => combinedSetupModels().gameParametersModel,
);

export const GameSetupParameterGroupsModel = ModelRegistry.register(
	"GameSetupParameterGroupsModel",
	ModelLifecycle.Singleton,
	() => combinedSetupModels().gameParametersByGroupModel,
);
